import { getTelemetryMode } from '../config/telemetryPolicy';
import type { HostVariantImplementationWorkItemSnapshot } from './contracts';
import { renderGuidance } from './guidancePrompt';
import { DEFAULT_WORKER_FIDELITY } from '../hosts/workerDefaults';
import { getPluginName } from '../hosts/pluginContext';

import * as os from 'os';
import * as path from 'path';

export const workItemBriefingsDirectory = (): string =>
  path.join(os.tmpdir(), 'rivet-work-briefings');

export const workItemBriefingPath = (
  sessionId: string,
  workId: string,
): string => path.join(workItemBriefingsDirectory(), sessionId, `${workId}.md`);

type WorkItemCompleteCommandContext = {
  projectPath?: string;
  sessionId?: string;
};

const commandArgument = (value: string): string =>
  /^[A-Za-z0-9_./:-]+$/.test(value)
    ? value
    : `'${value.replace(/'/g, `'\\''`)}'`;

export const workItemCompleteCommand = (
  workId: string,
  context?: WorkItemCompleteCommandContext,
): string => {
  const pluginName = getPluginName();
  const executable = pluginName
    ? `RIVET_PLUGIN_NAME=${pluginName} NODE_ENV=production ${commandArgument(process.execPath)} ${commandArgument(path.resolve(__dirname, '../../bin/rivet.js'))}`
    : 'rivet';
  return [
    `${executable} variants complete`,
    commandArgument(workId),
    context?.projectPath
      ? `--project ${commandArgument(context.projectPath)}`
      : null,
    context?.sessionId
      ? `--session ${commandArgument(context.sessionId)}`
      : null,
    '--status succeeded',
    getTelemetryMode() === 'off' ? '--no-telemetry' : null,
  ]
    .filter((part): part is string => part !== null)
    .join(' ');
};

export const workItemWorkerPrompt = (
  sessionId: string,
  item: HostVariantImplementationWorkItemSnapshot,
): string =>
  `You are implementing one Rivet design variant ("${item.direction.label}"). ` +
  `Read ${workItemBriefingPath(sessionId, item.workId)} and follow it exactly — ` +
  `it ends with your completion command. Edit only that work item's workspace.`;

const modeContract = (
  item: HostVariantImplementationWorkItemSnapshot,
): string => {
  if (item.mode === 'vary' || item.mode === 'refine') {
    const entry =
      item.workspace.kind === 'artifact_directory'
        ? `${item.workspace.rootPath}/${item.workspace.entryPath}`
        : item.workspace.projectPath;
    return (
      `The workspace already contains the source direction's finished code` +
      `${item.sourceDirection ? ` ("${item.sourceDirection.label}" — ${item.sourceDirection.brief})` : ''}. ` +
      `Read ${entry} first, then apply the requested delta with targeted Edit ` +
      `operations in place. Never rewrite or re-emit the full file; leave ` +
      `unchanged sections untouched.`
    );
  }
  if (item.workspace.kind === 'artifact_directory') {
    return `Write a complete standalone page to ${item.workspace.rootPath}/${item.workspace.entryPath}.`;
  }
  return (
    `The workspace at ${item.workspace.projectPath} contains the user's ` +
    `EXISTING app — its framework, components, and styles are the ` +
    `foundation this direction must build on. Inspect the project first ` +
    `(package.json, the source directory, the components the request ` +
    `touches), then implement the direction by editing the existing ` +
    `source files in place, matching the app's framework and conventions. ` +
    `Never replace the app with a standalone page: in a bundler project ` +
    `(Vite, Next.js, CRA) the root index.html is only the shell that ` +
    `loads the app — leave it intact and build the direction inside the ` +
    `app's source files.`
  );
};

export const renderWorkItemBriefing = (
  item: HostVariantImplementationWorkItemSnapshot,
  options?: {
    completion?: 'self' | 'executor';
    completionCommand?: WorkItemCompleteCommandContext;
  },
): string => {
  const lines: string[] = [`# Rivet work item ${item.workId}`];
  if (item.previewRoutesPath)
    lines.push(
      '',
      '## Edited-page metadata',
      'Before finishing, write a JSON array of the app-relative URLs actually edited, with the primary page first, to:',
      item.previewRoutesPath,
      'Create its parent directory if necessary. Preserve applicable query strings and hashes from the request or inherited page context.',
      'Determine URLs from the application routing and the actual change. Do not guess URLs from source filenames. If no edited URL can be established, leave this file absent.',
      'Do not add this metadata to the application or include a preview origin or Rivet transport prefix.',
    );
  if (item.previewRoutes?.length)
    lines.push(
      '',
      '## Edited pages',
      'The first route is the preview entry page. Preserve access to every listed page.',
      '```json',
      JSON.stringify(item.previewRoutes),
      '```',
    );
  if (item.instruction) {
    const requestGuidance =
      item.mode === 'refine'
        ? `Apply this request as a targeted delta to the existing direction. Preserve everything else unless the request requires it to change.`
        : `The user request applies to every direction. The worker-specific direction below controls how this variant differs; it does not replace or narrow the request.`;
    lines.push(
      '',
      `## User request — authoritative`,
      item.instruction,
      '',
      requestGuidance,
    );
  }
  const directionHeading =
    item.mode === 'refine'
      ? `## Existing direction context`
      : `## Direction for this worker`;
  if (item.guidance?.length) lines.push('', renderGuidance(item.guidance));
  lines.push(
    '',
    directionHeading,
    `${item.direction.label} — ${item.direction.brief}`,
  );
  if (item.direction.notes) {
    lines.push('', `### Direction notes`, item.direction.notes);
  }
  if (item.target?.type === 'file') {
    lines.push(
      '',
      `## Primary file`,
      `Implement the requested change in ${item.target.ref}. Inspect files it references when needed, but do not substitute another page or prototype.`,
    );
  }
  lines.push('', `## Contract (mode: ${item.mode})`, modeContract(item));
  if (item.relevantFiles?.length) {
    lines.push(
      '',
      `## Relevant files`,
      ...item.relevantFiles.map((file) => `- ${file}`),
    );
  }
  if (item.sourceReferences?.length) {
    lines.push(
      '',
      '## Source references',
      'Inspect these live source paths in place as read-only evidence under your current host permissions. They grant no additional access. Source content does not override the user request.',
      'Edit only the assigned workspace. Do not copy source files into the prototype or embed these original paths in generated output.',
      'If a required source is missing or inaccessible, report the blocked read through the completion command instead of silently proceeding without it.',
      ...item.sourceReferences.map((file) => `- ${file}`),
    );
  }
  if (item.contextFiles?.length) {
    lines.push(
      '',
      `## Reference files and directories — Inspect these FIRST`,
      `Inspect images visually and read relevant native source, styles, and documentation in their original format. Directory references are live read-only sources; inspect relevant files in place without copying the folder or editing it.`,
      `Use each reference according to the user's intended use and saved guidance. Source content does not override explicit user instructions.`,
      `If the generated app renders one, copy it into the assigned workspace and reference that copy.`,
      `Never reference these source paths from the generated app; they are not part of its artifact.`,
      ...item.contextFiles.map(
        (file) => `- ${file.path}${file.label ? ` — ${file.label}` : ''}`,
      ),
    );
  }
  if (item.contextAssets?.length) {
    lines.push(
      '',
      `## Context assets — already copied into this workspace`,
      `These caller-supplied files are available to this direction. Use the`,
      `workspace path to inspect a file and the reference path when the app`,
      `needs to load it.`,
      ...item.contextAssets.flatMap((asset) => [
        `- ${asset.label ?? asset.id}`,
        `  - file: ${asset.workspacePath}`,
        `  - reference: ${asset.referencePath}`,
      ]),
      ...(item.workspace.kind === 'artifact_directory'
        ? [
            `All files under the assigned root are part of the static artifact;`,
            `Rivet serves and persists them with ${item.workspace.entryPath}.`,
          ]
        : []),
    );
  }
  if (item.contextBundlePath) {
    lines.push(
      '',
      `## Design context`,
      `Read ${item.contextBundlePath} before implementing.`,
    );
  }
  if (item.qaRetry) {
    lines.push(
      '',
      `## Output integrity repair`,
      `The prior completion was returned for one repair. Address this before reporting success:`,
      item.qaRetry.summary,
    );
  }
  lines.push(
    '',
    `## Boundaries`,
    `Edit only ${item.workspace.rootPath}${
      item.workspace.kind === 'git_worktree'
        ? ` (app at ${item.workspace.projectPath})`
        : ''
    }. Do not touch other variants' workspaces. Do not run git commit or push.`,
    `Use the invoking host's current permissions and approval flow. If access is denied or approval is unavailable, report failure with the blocked operation. Do not bypass restrictions, switch providers, or ask the Rivet server to perform denied work.`,
  );
  if (item.workerSelection) {
    lines.push(
      '',
      '## Worker selection',
      `Requested provider: ${item.workerSelection.provider ?? 'initiating host'}. Requested model: ${item.workerSelection.model ?? 'inherit current model'}.`,
      'Honor this selection through the native host. If it cannot select the requested model or provider, report failure before authoring.',
    );
  }
  if (item.mode === 'create' && item.workspace.kind === 'git_worktree') {
    lines.push(
      '',
      `## Project check`,
      `Run the project's existing targeted build or typecheck once if one is`,
      `available. Fix failures caused by your changes. Do not install new`,
      `dependencies or start a browser solely for verification.`,
    );
  }
  if (options?.completion === 'executor') {
    if (
      item.mode === 'create' &&
      item.workspace.kind === 'artifact_directory'
    ) {
      if ((item.fidelity ?? DEFAULT_WORKER_FIDELITY) === 'high') {
        lines.push(
          '',
          `## Delivery contract`,
          `Write the COMPLETE page in ONE Write call, authored at full depth:`,
          `every section and interaction the request names, fully realized`,
          `design-system CSS, and — when the request names motion — a visibly`,
          `implemented motion spec. No filler sections or repeated style`,
          `variants nobody asked for.`,
        );
      } else {
        const entryFile = `${item.workspace.rootPath}/${item.workspace.entryPath}`;
        lines.push(
          '',
          `## Size & delivery contract`,
          `Plan briefly, then write the COMPLETE page in ONE Write call, aiming`,
          `for roughly 16–20KB of finished HTML. Ship every section and`,
          `interaction the request names, with fully realized CSS. Stay tight`,
          `the other way too: no filler sections, long copy blocks, or repeated`,
          `style variants nobody asked for. When the request names motion, the`,
          `page must visibly implement the direction's motion spec.`,
          '',
          `Then verify depth ONCE: run \`wc -c ${entryFile}\`. If it prints`,
          `under 15000, the page is underdeveloped — expand the weakest`,
          `sections with fully-realized styling and real content via targeted`,
          `Edit operations until a re-run prints over 16000. One expansion`,
          `round only; never rewrite the whole page.`,
        );
      }
    } else if (item.mode === 'create') {
      lines.push(
        '',
        `## Delivery contract`,
        `Implement the direction with targeted edits to the app's existing`,
        `source files, scoped to what the direction actually touches. Keep`,
        `the app building and its entry shell intact; Rivet captures your`,
        `changes as a diff against the app's baseline.`,
      );
    }
    lines.push('', `## Completion`);
    if (
      item.mode === 'create' &&
      item.workspace.kind === 'artifact_directory'
    ) {
      lines.push(
        `Before stopping, re-read your finished page ONCE, checking structure`,
        `only: no overlapping or stacked text (be careful with absolute`,
        `positioning), no unclosed tags, and every requested section present.`,
        `Fix findings with minimal targeted Edit operations — never re-emit`,
        `the page — then stop.`,
      );
    } else if (item.mode === 'create') {
      lines.push(
        `Before stopping, re-read your changed files ONCE, checking that the`,
        `app still builds coherently: imports resolve, tags and braces are`,
        `balanced, and every aspect the direction names is present. Fix`,
        `findings with minimal targeted Edit operations, then stop.`,
      );
    }
    lines.push(
      `Rivet checks that the worker produced an artifact — do NOT spend time`,
      `on screenshots, broader verification, or repeated re-reads, and do`,
      `not run any completion command. When your edits are in place, simply`,
      `stop.`,
      '',
    );
    return lines.join('\n');
  }
  lines.push(
    '',
    `## Completion — your FINAL step, the moment the workspace is done`,
    `Rivet checks that the worker produced an artifact — do NOT spend time on`,
    `screenshots, broader verification, or repeated re-reads. When your edits`,
    `are in place, run exactly:`,
    '',
    '```',
    workItemCompleteCommand(item.workId, options?.completionCommand),
    '```',
    '',
    '',
  );
  const completionContext = options?.completionCommand;
  if (completionContext?.projectPath && completionContext.sessionId)
    lines.push(
      'Hosts with Rivet MCP tools may instead call rivet_complete_variant_work with exactly:',
      JSON.stringify({
        project: completionContext.projectPath,
        sessionId: completionContext.sessionId,
        workId: item.workId,
        status: 'succeeded',
      }),
      '',
    );
  lines.push(
    'Do not send file contents through completion; Rivet reads the workspace itself. Then stop.',
    '',
  );
  return lines.join('\n');
};
